  qs jsonb := $q$[{"number":1,"instruction":"पृष्ठ का ओरिएंटेशन लैंडस्केप (Landscape) सेट करें।","marks":1.66,"criteria":[{"rule":"value","target":"pageLayout.aspectRatio","spec":{"regex":"^(29\\.7 ?/ ?21|1\\.414 ?/ ?1)$"}}],"solution":"1. PAGE LAYOUT → **Orientation ▾** → **Landscape**।\n\nजाँच: पेज चौड़ाई में (आड़ा)।"},{"number":2,"instruction":"द्वितीय व तृतीय पैराग्राफ की राइट इंडेंटेशन (Right Indentation) को 1.1\" सेट करें।","marks":1.66,"criteria":[{"rule":"value","kind":"body","place":1,"target":"blocks.0.attrs.marginRight","spec":{"regex":"^79\\.2(0*)pt$"}},{"rule":"value","kind":"body","place":2,"target":"blocks.0.attrs.marginRight","spec":{"regex":"^79\\.2(0*)pt$"}}],"solution":"1. दूसरा और तीसरा पैराग्राफ सेलेक्ट करें।\n2. HOME → Paragraph ग्रुप **↘** (Paragraph डायलॉग) → Indentation में **Right: 1.1\"** → **OK**।\n\nजाँच: दोनों पैराग्राफ दाईं ओर से अंदर।"},{"number":3,"instruction":"द्वितीय व तृतीय पैराग्राफ में 1.5 लाइन स्पेसिंग (Line Spacing) सेट करें।","marks":1.66,"criteria":[{"rule":"value","kind":"body","place":1,"target":"blocks.0.attrs.lineHeight","spec":{"regex":"^1\\.5(0*)$"}},{"rule":"value","kind":"body","place":2,"target":"blocks.0.attrs.lineHeight","spec":{"regex":"^1\\.5(0*)$"}}],"solution":"1. दूसरा और तीसरा पैराग्राफ सेलेक्ट करें।\n2. HOME → **Line and Paragraph Spacing ▾** → **1.5**।\n\nजाँच: लाइनों के बीच डेढ़ गुना जगह।"},{"number":4,"instruction":"प्रथम पैराग्राफ की बैकग्राउंड कलर / शेडिंग (Background Color/Shading) इफेक्ट को दूर (REMOVE) करें।","marks":1.66,"criteria":[{"rule":"value","kind":"body","place":0,"target":"blocks.0.attrs.backgroundColor","spec":[null,"","transparent","none","rgba(0, 0, 0, 0)"]}],"solution":"1. पहले पैराग्राफ में क्लिक करें।\n2. HOME → **Shading ▾** → **No Color** (No Fill)।\n\nजाँच: पहले पैराग्राफ के पीछे का रंग हट जाए।"},{"number":5,"instruction":"तृतीय पैराग्राफ के फॉन्ट कलर (Font Color) को ग्रीन (Green) व चतुर्थ पैराग्राफ के फॉन्ट कलर (Font Color) को डार्क रेड (Dark Red) सेट करें।","marks":1.66,"criteria":[{"rule":"words","kind":"body","place":2,"props":{"color":["00B050"]}},{"rule":"words","kind":"body","place":3,"props":{"color":["C00000"]}}],"solution":"1. तीसरा पैराग्राफ सेलेक्ट करें → HOME → **Font Color ▾** → Standard Colors में **Green**।\n2. चौथा पैराग्राफ सेलेक्ट करें → **Font Color ▾** → **Dark Red**।\n\nजाँच: तीसरा हरा, चौथा गहरा लाल।"},{"number":6,"instruction":"पृष्ठ (Page) के हेडर (Header) में पेज नम्बर डालें एवं पेज नम्बर 3 से स्टार्ट करें।","marks":1.66,"criteria":[{"rule":"run","kind":"header","props":{"field":{"regex":"^page-number\\|top\\|"},"text":{"regex":"^\\s*3\\s*$"}}}],"solution":"1. INSERT → **Page Number ▾** → **Top of Page** → **Plain Number 1** (कोई भी)।\n2. INSERT → **Page Number ▾** → **Format Page Numbers…** → **Start at: 3** → **OK**।\n3. **Close Header and Footer**।\n\nजाँच: हेडर में पेज नंबर 3।"},{"number":7,"instruction":"पहले पैराग्राफ के शब्द \"झंडे\" को सबस्क्रिप्ट इफेक्ट (Subscript effect) दें।","marks":1.66,"criteria":[{"rule":"text","kind":"body","place":0,"find":"झंडे","props":{"subscript":[true]}}],"solution":"1. पहले पैराग्राफ में \"झंडे\" शब्द सेलेक्ट करें।\n2. HOME → **Subscript (x₂)** (या Ctrl+=)।\n\nजाँच: \"झंडे\" लाइन से नीचे छोटा दिखे।"},{"number":8,"instruction":"द्वितीय व तृतीय पैराग्राफ का फॉन्ट साइज 15pt सेट करें।","marks":1.66,"criteria":[{"rule":"words","kind":"body","place":1,"props":{"fontSize":[15]}},{"rule":"words","kind":"body","place":2,"props":{"fontSize":[15]}}],"solution":"1. दूसरा और तीसरा पैराग्राफ सेलेक्ट करें।\n2. HOME → **Font Size** बॉक्स में **15** टाइप करके Enter।\n\nजाँच: दोनों पैराग्राफ का साइज 15।"},{"number":9,"instruction":"पृष्ठ में \"DO NOT COPY\" वॉटर मार्क अंकित करें।","marks":1.66,"criteria":[{"rule":"value","target":"pageLayout.watermark","spec":{"regex":"^\\s*do not copy\\s*$"}}],"solution":"1. DESIGN → **Watermark ▾** → **DO NOT COPY** (Disclaimers में)।\n\nजाँच: पेज पर तिरछा \"DO NOT COPY\"।"},{"number":10,"instruction":"पाँचवें पैराग्राफ की डबल स्ट्राइकथ्रू इफेक्ट (Double Strikethrough effect) दूर करें।","marks":1.66,"criteria":[{"rule":"words","kind":"body","place":4,"props":{"doubleStrike":[false,null]}}],"solution":"1. पाँचवाँ पैराग्राफ सेलेक्ट करें।\n2. HOME → Font ग्रुप **↘** (Ctrl+D) → Effects में **Double strikethrough** का ✔ हटाएँ → **OK**।\n\nजाँच: पाँचवें पैराग्राफ से दोहरी कटी लाइन हट जाए।"},{"number":11,"instruction":"चतुर्थ व पाँचवें पैराग्राफ को ब्लू कलर (Blue Color) टेक्स्ट हाईलाइट (Text Highlight) करें।","marks":1.66,"criteria":[{"rule":"words","kind":"body","place":3,"props":{"highlight":["0000FF"]}},{"rule":"words","kind":"body","place":4,"props":{"highlight":["0000FF"]}}],"solution":"1. चौथा और पाँचवाँ पैराग्राफ सेलेक्ट करें।\n2. HOME → **Text Highlight Color ▾** → **Blue**।\n\nजाँच: दोनों पैराग्राफ के पीछे नीला रंग।"},{"number":12,"instruction":"पृष्ठ की गटर (Gutter) वैल्यू 0.5\" व गटर पोजीशन (Gutter Position) टॉप (Top) सेट करें।","marks":1.66,"criteria":[{"rule":"value","target":"pageLayout.gutter","spec":{"regex":"^(12\\.7|1\\.27|0\\.5)(0*)(mm|cm|in)?$"}},{"rule":"value","target":"pageLayout.gutterPosition","spec":["top"]}],"solution":"1. PAGE LAYOUT → Page Setup ग्रुप **↘** (Page Setup डायलॉग) → **Margins**।\n2. **Gutter: 0.5\"** और **Gutter position: Top** → **OK**।\n\nजाँच: पेज के ऊपर का मार्जिन बढ़ जाए।"},{"number":13,"instruction":"टेबल के प्रथम स्तंभ (Column) के टेक्स्ट की अंडरलाइन इफेक्ट (Underline effect) दूर करें।","marks":1.66,"criteria":[{"rule":"table","place":0,"onlyColumn":0,"cellProps":{"underline":[false,null]}}],"solution":"1. टेबल का पहला कॉलम (क्र.सं.) सेलेक्ट करें।\n2. HOME → **Underline (U)** (Ctrl+U) दबाकर अंडरलाइन हटाएँ।\n\nजाँच: पहले कॉलम के अंकों के नीचे लाइन न रहे।"},{"number":14,"instruction":"टेबल के तृतीय स्तंभ (Column) के टेक्स्ट को बोल्ड (Bold) और फॉन्ट कलर (Font Color) लाल (Red Color) सेट करें।","marks":1.66,"criteria":[{"rule":"table","place":0,"onlyColumn":2,"cellProps":{"bold":[true],"color":["FF0000"]}}],"solution":"1. टेबल का तीसरा कॉलम (तिथि) सेलेक्ट करें।\n2. HOME → **Bold** (Ctrl+B) → **Font Color ▾** → **Red**।\n\nजाँच: तीसरा कॉलम बोल्ड और लाल।"},{"number":15,"instruction":"टेबल की प्रथम व तृतीय पंक्ति (Row) को जस्टिफाई अलाइनमेंट (Justify Align) सेट करें।","marks":1.76,"criteria":[{"rule":"table","place":0,"onlyRow":0,"cellProps":{"align":["justify"]}},{"rule":"table","place":0,"onlyRow":2,"cellProps":{"align":["justify"]}}],"solution":"1. टेबल की पहली पंक्ति सेलेक्ट करें → HOME → **Justify** (Ctrl+J)।\n2. तीसरी पंक्ति सेलेक्ट करें → **Justify**।\n\nजाँच: दोनों पंक्तियों का टेक्स्ट जस्टिफाई।"}]$q$::jsonb;
begin
  if exists (select 1 from public.word_efficiency_tests where language = 'Hindi' and title = 'EFFICIENCY TEST 21') then return; end if;
  select t.created_by as test_created_by, v.* into base from public.word_efficiency_tests t join public.word_efficiency_versions v on v.id = t.current_version_id
   where t.language = 'Hindi' and t.title = 'EFFICIENCY TEST 20';
  if base.id is null then raise exception 'Hindi Word EFFICIENCY TEST 20 not found (its settings are copied)'; end if;

  insert into public.word_efficiency_tests (slug, title, status, is_live, language, sequence, created_by, auto_publish_results, question_paper_ready, results_delay_minutes, current_version_number)
  values ('hindi-efficiency-test-21', 'EFFICIENCY TEST 21', 'draft', false, 'Hindi', 21, base.test_created_by, true, true, 15, 1)
  returning id into test_id;

  insert into public.word_efficiency_versions (test_id, version_number, title, language, description, instructions_markdown, delivery_onscreen, delivery_pdf, delivery_realfile,
      student_question_toggle, question_count, maximum_marks, duration_options, passing_marks, created_by, working_matter_snapshot, editor_capabilities, model_answer_snapshot)
  values (test_id, 1, 'EFFICIENCY TEST 21', 'Hindi', 'Previous-year exam paper (RSMSSB): Page Layout, Home, Insert and Design tab tasks on a Hindi document with a table: National Flag',
      base.instructions_markdown, true, false, false, base.student_question_toggle, jsonb_array_length(qs), 25, base.duration_options, base.passing_marks, base.created_by,
      matter, base.editor_capabilities, model)
  returning id into new_id;

  for q in select value from jsonb_array_elements(qs) loop
    insert into public.word_efficiency_questions (version_id, question_number, instruction, marks, section, display_order, is_visible, solution)
    values (new_id, (q->>'number')::integer, q->>'instruction', (q->>'marks')::numeric, null, (q->>'number')::integer, true, q->>'solution')
    returning id into question_id;
    insert into public.word_efficiency_grading_rules (version_id, question_id, exact_target, expected_operation, expected_value, allocated_marks, partial_marks, additional_criteria, part_label)
    values (new_id, question_id, 'rule', 'model-answer-match-v2', 'null'::jsonb, (q->>'marks')::numeric, null, q->'criteria', null);
  end loop;
  update public.word_efficiency_tests set current_version_id = new_id where id = test_id;

  select sum((public.word_efficiency_score_question(model, new_id, wq.id, wq.marks, model)).awarded),
         sum((public.word_efficiency_score_question(public.word_efficiency_initial_editor_document(matter), new_id, wq.id, wq.marks, model)).awarded)
    into model_gets, untouched_gets
    from public.word_efficiency_questions wq where wq.version_id = new_id;
  if model_gets <> 25 or untouched_gets <> 0 then
    raise exception 'Hindi Word Test 21 check failed: Model Answer gets %, untouched paper gets % (want 25 and 0)', model_gets, untouched_gets;
  end if;
  update public.word_efficiency_tests set status = 'published', published_at = now(), updated_at = now() where id = test_id;
end $$;
